func isOneEditDistance(s, t string) bool {
	if len(s) > len(t) {
		s, t = t, s
	}
	if len(t) > len(s)+1 {
		return false
	}
	for i := range s {
		if len(s) == len(t) && s[i] != t[i] {
			return s[i+1:] == t[i+1:]
		}
		if len(s) != len(t) && s[i] != t[i] {
			return s[i:] == t[i+1:]
		}
	}
	return len(t) == len(s)+1
}
